function typeSafeAdd(a, b) {
  if (typeof a !== 'number' || typeof b !== 'number') {
    throw new Error('Both arguments must be numbers');
  }
  return a + b;
}

function validateUser(obj) {
  if (!obj) return false;
  if (typeof obj.id !== 'number') return false;
  if (typeof obj.name !== 'string') return false;
  if (typeof obj.email !== 'string') return false;
  if (obj.role !== undefined && typeof obj.role !== 'string') return false;
  return true;
}

function createStack() {
  var items = [];
  return {
    push: function(item) { items.push(item); },
    pop: function() { return items.pop(); },
    peek: function() { return items[items.length - 1]; },
    isEmpty: function() { return items.length === 0; },
    size: function() { return items.length; }
  };
}

function formatValue(val) {
  if (Array.isArray(val)) return val.join(', ');
  if (typeof val === 'string') return val.toUpperCase();
  if (typeof val === 'number') return val.toFixed(2);
  if (typeof val === 'boolean') return val ? 'yes' : 'no';
  return String(val);
}

function delay(ms) {
  return new Promise(function(resolve) {
    setTimeout(function() { resolve('done'); }, ms);
  });
}
async function runSequence() {
  var r1 = await delay(1);
  var r2 = await delay(1);
  return [r1, r2];
}
